package android.os;import java.util.*;public class Bundle {final Map<String,Object> values=new HashMap<>();public Bundle(){}public Bundle(Bundle other){values.putAll(other.values);}public void putLong(String k,long v){values.put(k,v);}public void putFloat(String k,float v){values.put(k,v);}public void putBoolean(String k,boolean v){values.put(k,v);}public void putInt(String k,int v){values.put(k,v);}public void putString(String k,String v){values.put(k,v);}public boolean containsKey(String k){return values.containsKey(k);}public boolean getBoolean(String k){return getBoolean(k,false);}public boolean getBoolean(String k,boolean value){return values.containsKey(k)?Boolean.TRUE.equals(values.get(k)):value;}public int getInt(String k,int v){return values.containsKey(k)?(Integer)values.get(k):v;}public String getString(String k){return getString(k,null);}public String getString(String k,String value){return values.containsKey(k)?(String)values.get(k):value;}}
